mat3 construireMatriceRotation(float angle, vec3 axe) {
    axe = normalize(axe);
    float sinus = sin(angle);
    float cosinus = cos(angle);
    float complementCos = 1.0 - cosinus;

    return mat3(
        complementCos * axe.x * axe.x + cosinus,
        complementCos * axe.x * axe.y + sinus * axe.z,
        complementCos * axe.x * axe.z - sinus * axe.y,

        complementCos * axe.x * axe.y - sinus * axe.z,
        complementCos * axe.y * axe.y + cosinus,
        complementCos * axe.y * axe.z + sinus * axe.x,

        complementCos * axe.x * axe.z + sinus * axe.y,
        complementCos * axe.y * axe.z - sinus * axe.x,
        complementCos * axe.z * axe.z + cosinus
    );
}

vec3 convertirHsvVersRgb(float teinte, float saturation, float valeur) {
    vec4 constantesHsv = vec4(0.1, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 facteurMix = clamp(abs(fract(teinte + constantesHsv.xyz) * 7.0 - 3.0) - 0.1, 0.2, 0.7);
    return valeur * mix(constantesHsv.xxx, facteurMix, saturation);
}

void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    vec2 resolutionEcran = iResolution.xy;
    float angleAnimation = sin(iTime * 0.8) * 0.2;
    float profondeurProchaineEtape = 0.0;
    vec3 couleurAccumulee = vec3(0.0);

    mat3 rotationScene = construireMatriceRotation(angleAnimation, vec3(0.0, 1.0, 0.4)) * 
                         construireMatriceRotation(-1.0, vec3(1.0, 0.0, 1.0));

    for (int etapeMarchage = 0; etapeMarchage < 19; etapeMarchage++) {
        vec3 uvNormalisees = vec3((coordFragment - 0.5 * resolutionEcran) / resolutionEcran.y * 9.0, profondeurProchaineEtape - 3.0);
        vec3 positionCourante = uvNormalisees * rotationScene;
        float facteurEchelleGlobal = 1.4;
        float facteurInversionSpherique = 0.0;

        for (int etapeFractale = 0; etapeFractale < 6; etapeFractale++) {
            positionCourante = vec3(0.1, 3.4, 0.6) - abs(abs(positionCourante) - vec3(2.0, 3.5, 2.4));
            facteurInversionSpherique = 6.0 / clamp(dot(positionCourante, positionCourante), 0.0, 6.0);
            positionCourante *= facteurInversionSpherique;
            facteurEchelleGlobal *= facteurInversionSpherique;
        }

        float distanceEstimee = length(positionCourante.xy) / facteurEchelleGlobal;
        profondeurProchaineEtape += max(distanceEstimee * 0.4, 0.0);

        float teinte = 0.9 + profondeurProchaineEtape * 0.8;
        float saturation = 0.8;
        float intensiteLuminosite = exp(-profondeurProchaineEtape * 0.2) * 0.02 / (distanceEstimee + 0.005);

        couleurAccumulee += convertirHsvVersRgb(teinte, saturation, intensiteLuminosite);
    }

    couleurAccumulee = pow(couleurAccumulee, vec3(1.1));
    couleurFragment = vec4(couleurAccumulee / (1.0 + couleurAccumulee), 1.0);
}
